import * as THREE from "three";
import {chapterColor} from "./chapters";
export default function createScene({frames}) {
  const scene = new THREE.Scene();
  const camera = new THREE.OrthographicCamera(-1,1,1,-1,0,2);
  camera.position.z = 1;
  const material = new THREE.ShaderMaterial({
    uniforms: {color: {value: new THREE.Color()}},
    vertexShader: "void main(){gl_Position=vec4(position,1.0);}",
    fragmentShader: "uniform vec3 color; void main(){gl_FragColor=vec4(color,1.0);}",
    toneMapped: false,
  });
  scene.add(new THREE.Mesh(new THREE.PlaneGeometry(2,2),material));
  // Every update assigns absolute state, so chapter boundaries support seeking/retry.
  return {scene,camera,update({frame}) {material.uniforms.color.value.setRGB(...chapterColor(frame, frames));}};
}
